import type {
  ConditionalEffect,
  EquippedGear,
  GearDatabase,
  GearEffectKey,
  LightCone,
  RelicSet,
  StaticEffect
} from '../types/hsr';
import generated from './generated/gear.json';

/**
 * Generated by `npm run data` from StarRailRes. Do not hand-edit.
 *
 * Each entry is split into `staticEffects` — the always-on stat line, which a
 * build card's printed numbers already include — and `conditionalEffects`,
 * which they cannot. Only the conditional half is ever applied on top of an
 * imported stat line.
 */
export const GEAR_DB = generated as unknown as GearDatabase;

export const LIGHT_CONES: LightCone[] = GEAR_DB.lightCones;
export const RELIC_SETS: RelicSet[] = GEAR_DB.relicSets;

const CONE_BY_ID = new Map(LIGHT_CONES.map((cone) => [cone.id, cone]));
const CONE_BY_NAME = new Map(LIGHT_CONES.map((cone) => [normalise(cone.name), cone]));
const SET_BY_NAME = new Map(RELIC_SETS.map((set) => [normalise(set.name), set]));

function normalise(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, '');
}

export function findLightCone(idOrName: string | null | undefined): LightCone | undefined {
  if (!idOrName) return undefined;
  return CONE_BY_ID.get(idOrName) ?? CONE_BY_NAME.get(normalise(idOrName));
}

export function findRelicSet(name: string | null | undefined): RelicSet | undefined {
  return name ? SET_BY_NAME.get(normalise(name)) : undefined;
}

/** Names sorted longest first, so "Iron Cavalry Against the Scourge" wins over a prefix. */
export const RELIC_SET_NAMES: string[] = RELIC_SETS.map((set) => set.name).sort(
  (a, b) => b.length - a.length
);
export const LIGHT_CONE_NAMES: string[] = LIGHT_CONES.map((cone) => cone.name).sort(
  (a, b) => b.length - a.length
);

/** The always-on bonuses a build card already reflects, for display only. */
export function staticEffectsOf(gear: EquippedGear): StaticEffect[] {
  const effects: StaticEffect[] = [];

  const cone = findLightCone(gear.lightConeId ?? gear.lightCone);
  if (cone) {
    const tier = Math.min(Math.max(1, gear.superimposition), cone.staticEffects.length) - 1;
    effects.push(...(cone.staticEffects[tier] ?? []));
  }

  for (const equipped of gear.relicSets) {
    const set = findRelicSet(equipped.name);
    if (!set) continue;
    for (const bonus of set.bonuses) {
      if (equipped.pieces >= bonus.pieces) effects.push(...bonus.staticEffects);
    }
  }

  const planar = findRelicSet(gear.planarSet);
  for (const bonus of planar?.bonuses ?? []) {
    if (bonus.pieces === 2) effects.push(...bonus.staticEffects);
  }

  return effects;
}

export type GearTotals = Partial<Record<GearEffectKey, number>>;

function add(into: GearTotals, effect: ConditionalEffect, params: number[] | undefined) {
  const value =
    effect.value !== undefined
      ? effect.value
      : params && effect.paramIndex !== undefined
        ? (params[effect.paramIndex] ?? 0) * 100
        : 0;
  if (!Number.isFinite(value) || value <= 0) return;
  into[effect.key] = (into[effect.key] ?? 0) + value;
}

/**
 * The half of the wearer's gear a build card cannot show: light cone triggers,
 * 4-piece procs and planar conditions.
 *
 * These are modelled as always active. A conditional that is up for most of a
 * fight (Saber's post-Ultimate ATK, a 4-piece DMG bonus on Skill) reads close
 * to right; one gated on a rare state reads high. That is stated rather than
 * silently averaged, and it is still far closer than ignoring gear entirely.
 */
export function conditionalTotals(gear: EquippedGear): GearTotals {
  const totals: GearTotals = {};

  const cone = findLightCone(gear.lightConeId ?? gear.lightCone);
  if (cone) {
    const tier = Math.min(Math.max(1, gear.superimposition), cone.params.length) - 1;
    const params = cone.params[tier] ?? cone.params[0];
    for (const effect of cone.conditionalEffects) add(totals, effect, params);
  }

  for (const equipped of gear.relicSets) {
    const set = findRelicSet(equipped.name);
    if (!set) continue;
    for (const bonus of set.bonuses) {
      if (equipped.pieces >= bonus.pieces) {
        for (const effect of bonus.conditionalEffects) add(totals, effect, undefined);
      }
    }
  }

  const planar = findRelicSet(gear.planarSet);
  for (const bonus of planar?.bonuses ?? []) {
    if (bonus.pieces === 2) {
      for (const effect of bonus.conditionalEffects) add(totals, effect, undefined);
    }
  }

  return totals;
}

export function emptyGear(): EquippedGear {
  return { lightConeId: null, lightCone: '', superimposition: 1, relicSets: [], planarSet: '' };
}
